er-content-in-left data-[swipe-direction=right]:max-h-none data-[swipe-direction=right]:w-[min(22rem,calc(100vw-var(--moduix-spacing-8)))] data-[swipe-direction=right]:origin-right data-[swipe-direction=right]:rounded-l-xl data-[swipe-direction=right]:rounded-r-none data-[swipe-direction=right]:p-6 data-[swipe-direction=right]:after:inset-x-auto data-[swipe-direction=right]:after:inset-y-0 data-[swipe-direction=right]:after:left-full data-[swipe-direction=right]:after:h-auto data-[swipe-direction=right]:after:w-[var(--_drawer-bleed)] data-[swipe-direction=right]:data-[nested-drawer-open]:[translate:calc(-1*var(--moduix-spacing-10)*var(--nested-drawers,0))_0] data-[swipe-direction=right]:data-[state=closed]:animate-moduix-drawer-content-out-right data-[swipe-direction=right]:data-[state=open]:animate-moduix-drawer-content-in-right data-[swipe-direction=up]:origin-top data-[swipe-direction=up]:rounded-t-none data-[swipe-direction=up]:rounded-b-xl data-[swipe-direction=up]:pt-[calc(var(--moduix-spacing-4)+env(safe-area-inset-top,0px))] data-[swipe-direction=up]:pb-4 data-[swipe-direction=up]:after:top-auto data-[swipe-direction=up]:after:bottom-full data-[swipe-direction=up]:data-[nested-drawer-open]:[translate:0_calc(var(--moduix-spacing-10)*var(--nested-drawers,0))] data-[swipe-direction=up]:data-[state=closed]:animate-moduix-drawer-content-out-up data-[swipe-direction=up]:data-[state=open]:animate-moduix-drawer-content-in-up data-[variant=island]:rounded-xl data-[variant=island]:after:hidden data-[variant=island]:data-[swipe-direction=down]:[--_drawer-island-offset:max(var(--moduix-spacing-4),env(safe-area-inset-bottom,0px))] data-[variant=island]:data-[swipe-direction=left]:[--_drawer-island-offset:max(var(--moduix-spacing-4),env(safe-area-inset-left,0px))] data-[variant=island]:data-[swipe-direction=right]:[--_drawer-island-offset:max(var(--moduix-spacing-4),env(safe-area-inset-right,0px))] data-[variant=island]:data-[swipe-direction=up]:[--_drawer-island-offset:max(var(--moduix-spacing-4),env(safe-area-inset-top,0px))] motion-reduce:[transition-duration:1ms] motion-reduce:data-[state]:[animation-delay:0ms] motion-reduce:data-[state]:[animation-duration:1ms]",
          className,
        )}
        {...props}
        data-variant={variant}
        data-slot="drawer-content"
      />
    );
  },
);

const DrawerGrabber = forwardRef<
  ComponentRef<typeof DrawerPrimitive.Grabber>,
  ComponentProps<typeof DrawerPrimitive.Grabber>
>(function DrawerGrabber({ className, ...props }, ref) {
  return (
    <DrawerPrimitive.Grabber
      ref={ref}
      className={cn(
        'group/grabber flex w-full shrink-0 cursor-grab items-center justify-center pb-1 select-none group-data-[swipe-direction=left]/drawer:hidden group-data-[swipe-direction=right]/drawer:hidden active:cursor-grabbing',
        className,
      )}
      {...props}
      data-slot="drawer-grabber"
    />
  );
});

const DrawerGrabberIndicator = forwardRef<
  ComponentRef<typeof DrawerPrimitive.GrabberIndicator>,
  ComponentProps<typeof DrawerPrimitive.GrabberIndicator>
>(function DrawerGrabberIndicator({ className, ...props }, ref) {
  return (
    <DrawerPrimitive.GrabberIndicator
      ref={ref}
      className={cn(
        'h-1 w-12 rounded-full bg-muted-foreground opacity-[0.45] transition-opacity duration-200 ease-in-out motion-reduce:transition-none [@media(hover:hover)]:group-hover/grabber:opacity-70',
        className,
      )}
      {...props}
      data-slot="drawer-grabber-indicator"
    />
  );
});

const DrawerTitle = forwardRef<
  ComponentRef<typeof DrawerPrimitive.Title>,
  ComponentProps<typeof DrawerPrimitive.Title>
>(function DrawerTitle({ className, ...props }, ref) {
  return (
    <DrawerPrimitive.Title
      ref={ref}
      className={cn('text-lg font-semibold', className)}
      {...props}
      data-slot="drawer-title"
    />
  );
});

const DrawerDescription = forwardRef<
  ComponentRef<typeof DrawerPrimitive.Description>,
  ComponentProps<typeof DrawerPrimitive.Description>
>(function DrawerDescription({ className, ...props }, ref) {
  return (
    <DrawerPrimitive.Description
      ref={ref}
      className={cn('text-md text-muted-foreground', className)}
      {...props}
      data-slot="drawer-description"
    />
  );
});

const DrawerCloseTrigger = forwardRef<
  ComponentRef<typeof DrawerPrimitive.CloseTrigger>,
  ComponentProps<typeof DrawerPrimitive.CloseTrigger>
>(function DrawerCloseTrigger(props, ref) {
  return <DrawerPrimitive.CloseTrigger ref={ref} {...props} data-slot="drawer-close-trigger" />;
});

const DrawerCloseIcon = forwardRef<
  ComponentRef<typeof CloseButton>,
  Omit<ComponentProps<typeof DrawerPrimitive.CloseTrigger>, 'asChild'>
>(function DrawerCloseIcon(
  { className, children, 'aria-label': ariaLabel = a11yLabels.closeDrawer, ...props },
  ref,
) {
  return (
    <DrawerPrimitive.CloseTrigger asChild {...props}>
      <CloseButton
        ref={ref}
        data-slot="drawer-close-icon"
        aria-label={ariaLabel}
        className={cn(
          'rounded-md [@media(hover:hover)]:[&:not([data-disabled]):hover]:bg-accent [@media(hover:hover)]:[&:not([data-disabled]):hover]:text-popover-foreground',
          className,
        )}
      >
        {children}
      </CloseButton>
    </DrawerPrimitive.CloseTrigger>
  );
});

const DrawerSwipeArea = forwardRef<
  ComponentRef<typeof DrawerPrimitive.SwipeArea>,
  ComponentProps<typeof DrawerPrimitive.SwipeArea>
>(function DrawerSwipeArea({ className, ...props }, ref) {
  return (
    <DrawerPrimitive.SwipeArea
      ref={ref}
      className={cn(
        'fixed z-50 touch-none data-disabled:pointer-events-none data-[swipe-direction=down]:inset-x-0 data-[swipe-direction=down]:top-0 data-[swipe-direction=down]:h-10 data-[swipe-direction=left]:inset-y-0 data-[swipe-direction=left]:right-0 data-[swipe-direction=left]:w-10 data-[swipe-direction=right]:inset-y-0 data-[swipe-direction=right]:left-0 data-[swipe-direction=right]:w-10 data-[swipe-direction=up]:inset-x-0 data-[swipe-direction=up]:bottom-0 data-[swipe-direction=up]:h-10',
        className,
      )}
      {...props}
      data-slot="drawer-swipe-area"
    />
  );
});

const DrawerIndent = forwardRef<
  ComponentRef<typeof DrawerPrimitive.Indent>,
  ComponentProps<typeof DrawerPrimitive.Indent>
>(function DrawerIndent({ className, ...props }, ref) {
  return (
    <DrawerPrimitive.Indent
      ref={ref}
      className={cn(
        'relative origin-top [transition:transform_var(--moduix-transition-spring),border-radius_var(--moduix-transition-spring)] data-active:[transform:translateY(calc(var(--moduix-spacing-2)*(1-var(--drawer-swipe-progress,0))))_scale(calc(0.97+0.03*var(--drawer-swipe-progress,0)))] data-active:rounded-t-lg motion-reduce:[transition-duration:1ms]',
        className,
      )}
      {...props}
      data-slot="drawer-indent"
    />
  );
});

const DrawerIndentBackground = forwardRef<
  ComponentRef<typeof DrawerPrimitive.IndentBackground>,
  ComponentProps<typeof DrawerPrimitive.IndentBackground>
>(function DrawerIndentBackground({ className, ...props }, ref) {
  return (
    <DrawerPrimitive.IndentBackground
      ref={ref}
      className={cn(
        'pointer-events-none absolute inset-0 bg-foreground opacity-0 [transition:opacity_var(--moduix-transition-spring)] data-active:opacity-[calc(1-var(--drawer-swipe-progress,0))] motion-reduce:[transition-duration:1ms]',
        className,
      )}
      {...props}
      data-slot="drawer-indent-background"
    />
  );
});

const DrawerHeader = forwardRef<HTMLDivElement, HTMLArkProps<'div'>>(function DrawerHeader(
  { className, ...props },
  ref,
) {
  return (
    <ark.div
      ref={ref}
      className={cn(
        "grid grid-cols-[minmax(0,1fr)_auto] items-start gap-1 [&>[data-slot='drawer-close-icon']]:col-start-2 [&>[data-slot='drawer-description']]:col-span-2 [&>[data-slot='drawer-title']]:col-start-1",
        className,
      )}
      {...props}
      data-slot="drawer-header"
    />
  );
});

const DrawerBody = forwardRef<HTMLDivElement, HTMLArkProps<'div'>>(function DrawerBody(
  { className, ...props },
  ref,
) {
  return (
    <ark.div
      ref={ref}
      className={cn('mt-4 min-h-0 overflow-y-auto text-md', className)}
      {...props}
      data-slot="drawer-body"
    />
  );
});

const DrawerFooter = forwardRef<HTMLDivElement, HTMLArkProps<'div'>>(function DrawerFooter(
  { className, ...props },
  ref,
) {
  return (
    <ark.div
      ref={ref}
      className={cn('mt-6 flex flex-wrap justify-end gap-2', className)}
      {...props}
      data-slot="drawer-footer"
    />
  );
});

const DrawerContext = DrawerPrimitive.Context;

export {
  Drawer,
  DrawerBackdrop,
  DrawerBody,
  DrawerCloseIcon,
  DrawerCloseTrigger,
  DrawerContext,
  DrawerContent,
  DrawerDescription,
  DrawerFooter,
  DrawerGrabber,
  DrawerGrabberIndicator,
  DrawerHeader,
  DrawerIndent,
  DrawerIndentBackground,
  DrawerPositioner,
  DrawerRootProvider,
  DrawerStack,
  DrawerSwipeArea,
  DrawerTitle,
  DrawerTrigger,
  useDrawer,
  useDrawerContext,
  useDrawerStackContext,
};
export type { DrawerContentProps, DrawerRootProps, DrawerRootProviderProps, DrawerVariant };
